solve:{[tokens;codes]
  norm:{[x] t:(lower `$x);
    (t="1")|(t~`$"t")|((t~`$"true") and 4=count t)};

  longs:(); floats:(); bools:(); chars:(); syms:(); symidx:(); effective:""; recast:0;

  i:0;

  while[i<count tokens;
    token:tokens i; code:`$(codes i);
    matched:0;

    attempt:{[arg0;arg1]
      token:`$arg0;

      case arg1;
        "j": if[not any (token) in "0123456789";0b];
             if[not (count token);0b];
             v:"J"$token;
             if[abs[v]>=1000000000;0b];
             if[not all (token) in "0123456789-";0b];
             if[("-"~first token) and (not all ((1_token)) in "0123456789");0b];
             arg1:"j";1b;
        "f": if[not any (token) in "0123456789.";0b];
             v:"F"$token;
             if[abs[v]>=1000000f;0b];
             if[not all (token) in "0123456789.-";0b];
             if[not 1f = 100f * ((1000f * v) mod 0.001f);0b];
             arg1:"f";1b;
        "b": if[not norm[token];0b];
             arg1:"b";1b;
        "c": if[not 1=count token;0b];
             arg1:"c";1b;
        "s": arg1:"s";1b;
      ];

    attempt[token;`$code];

    if[not matched;
      attempts:"j","f","b","c","s";

      if[0 = code~"j";attempts:(attempts where not attempts~`"j")];
      if[0 = code~"f";attempts:(attempts where not attempts~`"f")];
      if[0 = code~"b";attempts:(attempts where not attempts~`"b")];
      if[0 = code~"c";attempts:(attempts where not attempts~`"c")];
      if[0 = code~"s";attempts:(attempts where not attempts~`"s")];

      j:0;
      while[j<count attempts;
        attempt[token;attempts j];
        if[matched;
          if[not `$codes[i]~attempts j;
            recast+:1
          ];
        ];
        j+:1;
      ];
    ];

    if[not matched;
      attempt[token;`"s"];
    ];

    effective,:enlist string `$codes i;

    case `$codes i;
      "j": longs,:enlist ("J"$token);
      "f": floats,:enlist ("F"$token);
      "b": bools,:enlist $[norm[token];1;0];
      "c": chars,:enlist "J"$token;
      "s":
        if[not token in syms;
          syms,:enlist token;
        ];
        symidx,:enlist syms?token;
    ];

    i+:1;
  ];

  total:(sum longs) + (sum floats) + (sum bools) + (sum chars) + (sum symidx);
  total:((10000f * total) mod 1000f);

  syms:distinct syms;

  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(effective;longs;floats;bools;chars;syms;symidx;recast;total);
  };
